from module_adapters._graph_extended_support import Diagram,validate
SOURCE='graphsage-modules/graphsage/encoders.py';AGG='graphsage-modules/graphsage/aggregators.py';KEY='graphsage_mean'
LINKS=[('nodes','neighbors','nodes','tensor'),('adj','neighbors','adj_lists','topology'),('neighbors','sample','neighbor_sets','topology'),('sample','unique','sets','topology'),('sample','mask','membership','topology'),('unique','mask','columns','topology'),('unique','lookup','ids','tensor'),('features','lookup','callable','callable'),('mask','mean','mask','tensor'),('lookup','mean','embeddings','tensor'),('nodes','selflookup','ids','tensor'),('features','selflookup','callable','callable'),('selflookup','concat','self','tensor'),('mean','concat','neighbors','tensor'),('concat','project.transpose','in','tensor'),('weight','project.mm','W','parameter_operand'),('project.relu','output','in','tensor')]
REQUIRED={'features':dict(external_callable=True,instance_identity='shared features callable',parameter_registration='unknown at boundary'),'sample':dict(num_sample=10,method='random.sample only for degree>=10'),'mask':dict(normalization='row count',epsilon_added=False),'concat':dict(ordered_operands=['self_feats','neigh_feats'],dim=1),'weight':dict(parameter='Encoder.weight',shape='[4,16]'),'project.mm':dict(expression='self.weight.mm(combined.t())',ordered_operands=['weight','combined.t()']),'project.relu':dict(shape='[4,M]')}
CONTRACTS=[('Encoder.forward','self.aggregator.forward(nodes, [self.adj_lists[int(node)] for node in nodes], self.num_sample)'),('Encoder.forward','torch.cat([self_feats, neigh_feats], dim=1)'),('Encoder.forward','F.relu(self.weight.mm(combined.t()))'),('Encoder.__init__','torch.FloatTensor(embed_dim, self.feat_dim if self.gcn else 2 * self.feat_dim)')]
