def build():
 d=Diagram(KEY,'GraphSAGE sampled mean',SOURCE,'Encoder.forward','One Encoder with MeanAggregator, gcn=False, cuda=False, num_sample10; excludes classifier and multi-layer task network.',dict(feature_dim=8,embed_dim=4,num_sample=10,gcn=False,cuda=False,output_orientation='[embed_dim,M]',nonempty_neighbors_assumed=True,feature_callable_shared=True))
 agg=d.ref('MeanAggregator.forward',AGG);init=d.ref('Encoder.__init__')
 d.input('nodes','Queried node IDs','[M]');d.input('adj','Supplied adjacency lists','neighbor sets',kind='control');d.input('features','Shared feature callable','IDs -> [count,8]',kind='control',**REQUIRED['features']);d.input('weight','Owned Encoder weight','[4,16]',kind='parameter',source=init,parameter='Encoder.weight')
 d.node('neighbors','Read queried neighbor sets','control','M sets',0)
 d.node('sample','Sample up to10 neighbors','control','M sampled sets',1,source=agg,**REQUIRED['sample'])
 d.node('unique','Union / unique node IDs','tensor','[U]',2,source=agg,unordered_set_enumeration=True)
 d.node('mask','Binary membership / row divide','normalize','[M,U]',3,source=agg,**REQUIRED['mask'])
 d.node('lookup','Query features(unique IDs)','embedding','[U,8]',3,source=agg,instance_identity='shared features callable')
 d.node('selflookup','Query SAME features(nodes)','embedding','[M,8]',4,instance_identity='shared features callable')
 d.node('mean','mask @ neighbor embeddings','matmul','[M,8]',4,source=agg,expression='mask.mm(embed_matrix)')
 d.node('concat','Concat SELF then NEIGHBOR','cat','[M,16]',5,**REQUIRED['concat'])
 d.stage('project','Projection / transposed node axis','[4,M]',6,[('transpose','Transpose combined','tensor','[16,M]',dict(expression='combined.t()')),('mm','W @ combined transpose','matmul','[4,M]',REQUIRED['project.mm']),('relu','ReLU / retain [embed_dim,M]','relu','[4,M]',dict())])
 for s,t,p,r in LINKS:d.edge(s,t,p,r,ss='left' if s=='features' else 'out',ds='left' if t=='project.mm' else 'in')
 return d.build(d.entry,'[4,M]','GraphSAGEMean.md',['Neighbor sampling, membership-mask normalization and matrix multiplication are source operations; a textbook abstract mean glyph alone would hide these steps.','Both self and neighbor lookups call the SAME externally supplied features callable. Its parameter ownership is unknown at this module boundary.','Encoder owns weight[4,16], with no bias, and multiplies W by combined.t(); output is [4,M], not [M,4].','Selected gcn=False bypasses the source gcn=True set-addition branch. Nonempty neighborhoods are assumed for static shape discussion; division has no epsilon.','Frozen repository has no license file; README is retained and no license is invented.'],['Do not include queried node itself in sampled neighbors under the selected gcn=False branch.','Do not infer separate learned embedding tables from the two lookup glyphs or silently transpose the returned output.'])
def validate_ir(ir):return validate(ir,KEY,REQUIRED,LINKS,dict(gcn=False,output_orientation='[embed_dim,M]',feature_callable_shared=True))
